"""Build the static client review website from shared components and one form master."""
from pathlib import Path
from html import escape as e
import json,re

ROOT=Path(__file__).parent
C=json.loads((ROOT/'site-config.json').read_text(encoding='utf-8'))
A=C['audiences']
PAGES={
'client':dict(title='Consulting expertise for your business | OptimIQ Consultus',description='Find assessed consultants, strategic advisors and project managers. Discuss your project or explore an optional fee comparison.',eyebrow='FOR ORGANISATIONS & BUSINESS LEADERS',headline='Experienced consultants for critical business projects.',intro='Access independently assessed consultants, strategic advisors and project managers. Work with proven talent under clear, agreed terms, supported by initial project scoping.',primary='Discuss a Project Requirement',secondary='Compare Project Fees',film='How OptimIQ helps you find the right expertise.',takeaways=[('Assessed talent','Experience and completed work are reviewed before introduction.'),('Scoping support','A Solution Coordinator helps clarify initial requirements.'),('Flexible working models','On-site, remote or hybrid arrangements are agreed in advance.')],overview='OptimIQ helps you define the expertise your project needs. Consultants and firms are assessed, and a Solution Coordinator supports initial requirements and routing. Working arrangements, scope and payment terms are agreed for each engagement. Optional Project Success Management provides agreed delivery oversight.',faqs=[('How are consultants assessed?','Assessment considers domain capability, behaviour under pressure, stakeholder navigation and outcome ownership. Relevant experience and past work support the evaluation.'),('Who supports project delivery?','A Solution Coordinator supports initial scoping and onboarding. Optional Project Success Management provides delivery oversight under an agreed scope and terms.'),('How are fees and payments agreed?','Rates, project stages and payment schedules are agreed in advance. Terms may include mobilisation payments; completed milestones follow review and the agreed contract.'),('Can consultants work on-site or remotely?','On-site, remote and hybrid arrangements depend on the project requirement and consultant availability.'),('How is sensitive project information handled?','Our team discusses suitable safeguards before sensitive information is shared. Please keep confidential documents out of the initial enquiry.')]),
'expert':dict(title='Independent consulting opportunities | OptimIQ Consultus',description='Apply to OptimIQ as a consultant, strategic advisor or project manager. Explore assessment and an optional earnings example.',eyebrow='FOR CONSULTANTS, STRATEGIC ADVISORS & PROJECT MANAGERS',headline='Great work should not depend on a famous employer.',intro='OptimIQ evaluates your experience and completed project results. Apply to be considered for consulting opportunities across the Gulf and internationally.',primary='Apply to Join OptimIQ',secondary='View Earnings Example',film='Independent evaluation and relevant opportunities.',takeaways=[('Evaluated delivery','Your experience and completed project results inform assessment.'),('Verified capability','Evidence and professional discussion support evaluation.'),('Relevant matching','Opportunities depend on capability, availability and client demand.')],overview='Begin with a short application. Email verification and a private profile follow through the approved onboarding process. Your experience, evidence and professional discussion inform quality review. Assessed standing and relevant matching depend on evaluation and client demand; application does not guarantee certification or work.',faqs=[('What do I need for the initial application?','Your full name, professional email and consulting experience band. Role, practice area, phone and LinkedIn are optional. CVs and detailed evidence are collected later in the private profile.'),('Does applying guarantee certification or projects?','No. Assessed standing depends on evaluation and supporting evidence. Project opportunities depend on client requirements, relevant capability and availability.'),('Are my identity and contact details public?','They remain private during matching. Any identifying introduction follows the approved platform process and required terms.'),('Do I have to share my earnings example?','No. The calculator is optional. Its commercial figures are included only when you confirm the calculation and separately choose to attach it.'),('What happens after I apply?','The application is recorded through the production service. Email verification and the private evidence step follow the approved onboarding process. The team will explain any further requirements.')]),
'firm':dict(title='Consulting firm partnerships | OptimIQ Consultus',description='Explore independent assessment, specialist capacity and relevant opportunities while keeping your consulting firm’s identity.',eyebrow='FOR BOUTIQUE & MID-SIZED CONSULTING FIRMS',headline='Compete on merit. Win larger business projects.',intro='Explore independent assessment and additional specialist capacity while keeping your firm’s identity. Relevant opportunities depend on client requirements and consultant availability.',primary='Discuss a Firm Partnership',secondary='Estimate Missed Opportunities',film='How OptimIQ helps your practice scale.',takeaways=[('Independent evaluation','Firm capabilities and relevant evidence inform assessment.'),('Additional specialist capacity','Explore expertise to support an agreed requirement, subject to availability.'),('Your firm’s identity','Keep your firm’s identity when you pursue opportunities through OptimIQ.')],overview='Start with a partnership enquiry. The team explores your firm’s capabilities, practice coverage and intended collaboration. Assessment and relevant availability support matching to client requirements. Keep your firm’s identity when you pursue opportunities through OptimIQ. Delivery arrangements and commercial terms are agreed for each engagement.',faqs=[('Will our firm keep its identity?','Yes. You keep your firm’s identity when you pursue opportunities through OptimIQ. Client introductions follow agreed platform terms.'),('Are individual practitioners assessed?','Individual practitioners may follow the appropriate quality assessment process. Firm assessment, practitioner assessment and commercial agreements are distinct activities.'),('Does assessment guarantee introductions?','No. Eligibility depends on verified capabilities, relevant availability and client requirements. Opportunities and capacity are not guaranteed.'),('Can we seek projects and additional capacity?','Yes. You may express interest in new project opportunities, additional consultant capacity, or both. Neither choice is required for the initial enquiry.'),('Is an NDA already in place when we enquire?','An initial enquiry does not itself put an NDA in force. Discuss appropriate arrangements before sharing confidential client records or proprietary firm information.')])}

def route(a,prefix=''):
 return prefix+A[a]['route']+'/'
def action(a,label=None,prefix='',current='home',klass='button'):
 href=('#'+A[a]['formAnchor']) if current in ('home',a) else route(a,prefix)+'#'+A[a]['formAnchor']
 return f'<a class="{klass}" href="{href}" data-register="{a}">{e(label or A[a]["action"])} <span aria-hidden="true">↗</span></a>'
def brand(prefix):
 return f'<a class="brand" href="{prefix}index.html" aria-label="OptimIQ Consultus home"><img src="{prefix}../public-website/assets/OptimIQ_Short_logo.png" width="44" height="44" alt=""><span><b>OptimIQ</b><small>Consultus</small></span></a>'
def header(current,prefix):
 links=''.join(f'<a href="{route(a,prefix)}"'+(' aria-current="page"' if a==current else '')+f'>{e("For "+A[a]["name"].lower())}</a>' for a in A)
 opts=''.join(action(a,{'client':'I need consulting expertise','expert':'I am a consultant or advisor','firm':'I lead a consulting firm'}[a],prefix,current,'') for a in A)
 return f'<a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner">{brand(prefix)}<nav aria-label="Main navigation">{links}<a href="{prefix}index.html#why-optimiq">Why OptimIQ</a></nav><div class="register-menu"><button id="register-toggle" aria-expanded="false" aria-controls="register-options">Register <span aria-hidden="true">↗</span></button><div id="register-options" hidden>{opts}</div></div></div></header>'
def footer(prefix):
 links=''.join(f'<a href="{route(a,prefix)}">For {e(A[a]["name"].lower())} ↗</a>' for a in A)
 return f'<div class="footer-surface"><footer class="wrap footer">{brand(prefix)}<div>{links}</div><div><button class="policy-link" type="button">Privacy Notice</button><a href="{prefix}index.html#enquiries">General enquiries ↗</a></div><small>© 2026 OptimIQ Consultus</small></footer></div>'
def field(f,a):
 name=f['name'];label=e(f['label']);ident=f'{a}-{name}';req=' required' if f.get('required') else '';mark='<span aria-hidden="true">*</span>' if req else '<small>(optional)</small>';typ=f.get('type','text')
 attrs=f'id="{ident}" name="{name}" aria-describedby="{ident}-hint {ident}-error"'+req
 if typ in ('practice','role','experience'):
  choices=C['practiceAreas'] if typ=='practice' else [{'id':x,'label':x} for x in C['roles' if typ=='role' else 'experienceBands']]
  control=f'<select {attrs}><option value="">Select {"a practice area" if typ=="practice" else "a role" if typ=="role" else "your experience"}</option>'+''.join(f'<option value="{e(x["id"])}">{e(x["label"])}</option>' for x in choices)+'</select>'
 elif typ=='textarea':control=f'<textarea {attrs} maxlength="{f["max"]}" rows="3"></textarea>'
 else:control=f'<input {attrs} type="{typ}"'+(f' minlength="{f["min"]}"' if f.get('min') else '')+(f' maxlength="{f["max"]}"' if f.get('max') else '')+(f' autocomplete="{f["autocomplete"]}"' if f.get('autocomplete') else '')+'>'
 return f'<label class="form-field" for="{ident}">{label} {mark}{control}<span class="field-hint" id="{ident}-hint">{e(f.get("hint",""))}</span><span class="field-error" id="{ident}-error" hidden></span></label>'
def form(a,current,drawer=False):
 d=A[a];title={'client':'Discuss your project requirements.','expert':'Apply to join OptimIQ.','firm':'Discuss a partnership with our team.'}[a]
 desc={'client':'Share your contact information and a brief note on what you need. Our client team will contact you to discuss your project scope, timeline and candidate availability.','expert':'Start with your contact information and consulting experience. Email verification and your private experience record follow through the approved onboarding process.','firm':'Share your firm’s background to begin the conversation. Our partnerships team will contact you to discuss how we can work together.'}[a]
 notice={'client':'Please do not include confidential documents or sensitive project information in this initial enquiry.','expert':'Your identity and contact details remain private during matching. Identifying introductions follow the approved platform process and required terms.','firm':'Please do not include confidential client records or proprietary firm information in this initial enquiry.'}[a]
 fields=''.join(field(f,a) for f in d['fields'])
 interests='<fieldset class="interest-choice"><legend>What interests your firm? <span>(optional)</span></legend><label class="check-line"><input name="new_project_opportunities" type="checkbox"><span>New project opportunities</span></label><label class="check-line"><input name="additional_consultant_capacity" type="checkbox"><span>Additional consultant capacity</span></label></fieldset>' if a=='firm' else ''
 attach='<label class="check-line attachment-choice"><input name="attach_earnings_calculation" type="checkbox" disabled><span>Attach my confirmed earnings calculation (optional)</span></label><p class="attachment-help">You can apply without an earnings example. Confirm the calculation to enable this option.</p>' if a=='expert' else '<p class="attachment-help">You can continue without a calculation.</p>'
 close='<button class="close-button" type="button" data-close-form>Close ×</button>' if drawer else ''
 return f'<section class="registration-panel {"home-drawer" if drawer else "audience-form"}" id="{d["formAnchor"]}" data-form-section="{a}" aria-labelledby="{a}-form-heading" {"hidden" if drawer else ""}><form data-contact-form="{a}" novalidate><div class="form-heading"><div><p class="eyebrow">YOUR NEXT STEP</p><h2 id="{a}-form-heading" tabindex="-1">{title}</h2></div>{close}</div><p class="form-intro">{desc}</p><div class="error-summary" role="alert" hidden></div><div class="form-grid">{fields}</div>{interests}<div class="attachment"><div class="scenario-summary" hidden><div><strong>Calculation attached</strong><p></p></div><button type="button" class="text-link" data-remove-scenario>Remove</button></div>{attach}</div><p class="form-privacy">We handle your information in accordance with our <button class="policy-link" type="button">Privacy Notice</button>. {notice}</p><div class="honeypot" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="form-bottom"><button class="button" type="submit" disabled>{d["submit"]} <span aria-hidden="true">↗</span></button><p class="preview-note">Review preview · no information is sent.</p></div><div class="submit-status" role="status" tabindex="-1"></div><div class="form-confirmation" tabindex="-1" hidden><h3></h3><p></p></div></form></section>'
def numeric(a,f):
 name=f['name'];ident=f'{a}-{name}-number';value=f['default'];isdiscrete=f.get('discrete');lo=0 if isdiscrete else f.get('min',0);hi=len(C['projectValues'])-1 if isdiscrete else f.get('max',100);step=1 if isdiscrete else f.get('step',1);pos=C['projectValues'].index(value) if isdiscrete else value
 if f.get('choices'):
  controls='<fieldset class="growth-choice"><legend class="sr-only">Target daily rate increase</legend>'+''.join(f'<label><input type="radio" data-calc-input="{name}" name="growth-example" value="{v}" '+('checked' if v==value else '')+f'>+{v}%</label>' for v in f['choices'])+'</fieldset>'
 elif isdiscrete:
  controls=f'<div class="slider-input"><input type="range" min="0" max="13" step="1" value="{pos}" data-calc-range="{name}" aria-label="Average project value slider"><select id="{ident}" data-calc-input="{name}" aria-label="Average project value in USD">'+''.join(f'<option value="{v}" '+('selected' if v==value else '')+f'>${v:,}</option>' for v in C['projectValues'])+'</select></div>'
 else:controls=f'<div class="slider-input"><input type="range" min="{lo}" max="{hi}" step="{step}" value="{value}" data-calc-range="{name}" aria-label="{e(f["label"])} slider"><input id="{ident}" type="number" min="{lo}" max="{hi}" step="{step}" value="{value}" data-calc-input="{name}" inputmode="numeric" required aria-label="{e(f["label"])}" aria-describedby="{a}-{name}-error"></div>'
 label=f'<span>{e(f["label"])}</span>' if f.get('choices') else f'<label for="{ident}">{e(f["label"])}</label>'
 return f'<div class="tool-field"><div class="field-heading">{label}<span>{f["unit"]}</span></div>{controls}<label class="check-line input-confirm"><input type="checkbox" data-confirm="{name}"><span>Confirm this value</span><small data-confirm-state="{name}">Example</small></label><p class="field-error" id="{a}-{name}-error" data-calc-error="{name}" hidden></p></div>'
def calculator(a,current,home=False):
 d=A[a];anchor=d['homeToolAnchor'] if home else d['toolAnchor'];role='<fieldset class="role-choice"><legend>Explore a professional role (optional)</legend>'+''.join(f'<label><input type="radio" name="calculator-role" value="{r}" data-role-choice>{r}</label>' for r in C['roles'])+'</fieldset>' if a=='expert' else ''
 note={'client':'The target daily rate is chosen by you as an illustrative figure and does not represent an OptimIQ fee quotation.','expert':'Your chosen target is an example of possible billings, before fees, taxes and business expenses. Work and earnings depend on actual engagements.','firm':'The gross value of projects lost or declined in the past year. This is not recovered revenue or a prediction of future work.'}[a]
 confirm='Confirm calculation and continue' if a=='expert' else 'Confirm figures and attach to enquiry'
 close='<button class="close-button" type="button" data-close-tool>Close ×</button>' if home else '<span class="optional-label">Optional tool</span>'
 return f'<section id="{anchor}" class="tool-panel" data-calculator="{a}" aria-labelledby="{a}-calculator-heading" {"hidden" if home else ""}><div class="tool-heading"><div><p class="eyebrow">YOUR FIGURES, YOUR SCENARIO</p><h2 id="{a}-calculator-heading" tabindex="-1">{d["title"]}</h2></div>{close}</div>{role}<div class="tool-layout"><div class="tool-inputs">'+''.join(numeric(a,f) for f in d['inputs'])+f'{"<p class=field-note>Billable days are days you expect to charge clients for.</p>" if a=="expert" else ""}</div><div class="tool-result" aria-live="polite" aria-atomic="true"><span class="result-state">Based on example figures</span><h3></h3><div class="result-details"></div><strong class="result-total"></strong><p class="result-note">{note}</p><button class="button" type="button" data-confirm-calculation>{confirm} <span aria-hidden="true">→</span></button>{action(a,"Continue without a calculation",current=current,klass="text-link")}</div></div><p class="tool-bottom" data-remaining>Example figures are shown. Confirm the displayed figures only if they reflect your chosen scenario.</p></section>'
def video(current,prefix):
 home=current=='home';p=None if home else PAGES[current];heading='See how OptimIQ works.' if home else p['film'];overview='OptimIQ connects organisations with assessed consultants and consulting firms. A Solution Coordinator supports scoping and routing. Optional Project Success Management provides agreed delivery oversight. Scope, stages and payment terms, including any mobilisation payments, are agreed for each engagement.' if home else p['overview']
 takeaways=[('Assessed experts','Skills and past work are reviewed.'),('Managed matching','Expertise is matched to project needs.'),('Clear project terms','Scope, stages and payment terms are agreed upfront.')] if home else p['takeaways']
 actions=''.join(action(a,None,prefix,current,'action-line') for a in A) if home else action(current,PAGES[current]['primary'],prefix,current)
 return f'<section class="wrap video-section" id="video"><div class="section-heading"><p class="eyebrow">THE BIG PICTURE</p><h2 data-core>{heading}</h2></div><div class="video-layout"><div class="film-module" data-film="{current}"><video controls playsinline preload="none" aria-label="{e(heading)}" hidden></video><button class="video-poster" data-play aria-controls="film-fallback" aria-expanded="false"><img src="{prefix}../public-website/assets/collaboration.jpg" width="1800" height="1202" alt="" loading="lazy"><span class="poster-title">{heading}</span><span class="play-icon" aria-hidden="true">▶</span><span class="poster-caption">Explainer preview</span></button><div id="film-fallback" class="video-fallback" role="status" hidden><strong>This film is not available yet.</strong><p>Read the overview below or continue with your enquiry.</p><button class="text-link" data-retry-video type="button">Try playback again ↗</button></div><details class="transcript"><summary>Read the overview <span aria-hidden="true">+</span></summary><p>{overview}</p></details></div><aside class="video-aside"><p class="eyebrow">YOUR NEXT STEP</p><h3>{"Choose what comes next." if home else "Start with a conversation."}</h3><p>Continue when you are ready. Watching the film is optional.</p>{actions}</aside></div><div class="takeaways" id="{("why-optimiq" if home else "video-takeaways")}">'+('<h3 class="takeaway-heading">Why choose OptimIQ?</h3>' if home else '')+'<div class="trust-grid">'+''.join(f'<article><span class="trust-icon" aria-hidden="true">{i+1:02}</span><h3 data-core>{e(t)}</h3><p data-core>{e(s)}</p></article>' for i,(t,s) in enumerate(takeaways))+'</div></div></section>'
def rolecards(selectable=False):
 roles=[('Consultant','Hands-on expertise for defined business workstreams.'),('Strategic Advisor','Experienced guidance for senior commercial and organisational decisions.'),('Project Manager','Coordination of teams, milestones and project progress.')]
 return '<div class="role-cards">'+''.join(f'<article class="role-card"><span class="role-index">0{i+1}</span><h3 data-core>{r}</h3><p data-core>{s}</p>'+ (f'<button class="text-link" type="button" data-role-card="{r}" aria-pressed="false">Choose role <span aria-hidden="true">→</span></button>' if selectable else '')+'</article>' for i,(r,s) in enumerate(roles))+'</div>'
def practice():return '<div class="practice-grid">'+''.join(f'<div><span aria-hidden="true">{i+1:02}</span><h3>{e(x["label"])}</h3></div>' for i,x in enumerate(C['practiceAreas']))+'</div>'
def journey(items):return '<ol class="journey-steps">'+''.join(f'<li><span aria-hidden="true">{i+1:02}</span><strong data-core>{e(s)}</strong></li>' for i,s in enumerate(items))+'</ol>'
def faq(a):return '<section class="wrap content-section faq-section" id="faqs"><div class="section-heading"><p class="eyebrow">GOOD TO KNOW</p><h2>Frequently asked questions</h2></div><div class="faqs">'+''.join(f'<article><h3><button class="faq-toggle" aria-expanded="false" aria-controls="faq-{i}">{e(q)}<span aria-hidden="true">+</span></button></h3><div class="faq-answer" id="faq-{i}" hidden><p>{e(ans)}</p></div></article>' for i,(q,ans) in enumerate(PAGES[a]['faqs']))+'</div></section>'
def guide(a):
 asset=C['guides'].get(a)
 if not asset or not asset.get('approved') or not asset.get('url'):return ''
 anchor={'client':'client-guide','expert':'professional-guide','firm':'firm-guide'}[a]
 return f'<section class="wrap content-section" id="{anchor}"><h2>{e(asset["title"])}</h2><p>Request your copy. This is a guide request, separate from an application or enquiry.</p><form data-contact-form="guide" data-guide-audience="{a}" novalidate><div class="error-summary" role="alert" hidden></div><div class="form-grid">'+field(dict(name='full_name',label='Full name',required=True,min=2,max=160,autocomplete='name'),'guide')+field(dict(name='email',label='Professional email' if a=='expert' else 'Email address',required=True,type='email',max=254,autocomplete='email'),'guide')+f'</div><p class="form-privacy">We handle your information in accordance with our <button class="policy-link" type="button">Privacy Notice</button>.</p><div class="honeypot" aria-hidden="true"><label>Leave empty<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="form-bottom"><button class="button" type="submit" disabled>Request the guide →</button><p class="preview-note">Review preview · no information is sent.</p></div><div class="submit-status" role="status" tabindex="-1"></div><div class="form-confirmation" hidden tabindex="-1"><h3></h3><p></p><a class="button" href="{e(asset["url"])}" download>Download the guide ↓</a></div></form></section>'
def general():
 fields=[dict(name='full_name',label='Full name',required=True,min=2,max=160,autocomplete='name'),dict(name='email',label='Email address',required=True,type='email',max=254,autocomplete='email'),dict(name='organisation',label='Organisation',max=200,autocomplete='organization'),dict(name='phone',label='Phone or WhatsApp',type='tel',max=60,autocomplete='tel')]
 return '<section class="wrap enquiries" id="enquiries"><div class="enquiry-top"><div><h2>General questions?</h2><p>For media, institutional collaboration and general correspondence.</p></div><button id="enquiry-toggle" class="text-link" aria-expanded="false" aria-controls="general-form">Send us a message <span aria-hidden="true">↗</span></button></div><form class="general-form" id="general-form" data-contact-form="general" novalidate hidden><div class="form-heading"><h3 tabindex="-1" id="general-form-heading">Send us a message</h3><button class="close-button" type="button" id="enquiry-close">Close ×</button></div><div class="error-summary" role="alert" hidden></div><div class="form-grid">'+''.join(field(f,'general') for f in fields)+field(dict(name='category',label='Enquiry type',required=True),'general').replace('<input id="general-category" name="category" aria-describedby="general-category-hint general-category-error" required type="text">','<select id="general-category" name="category" aria-describedby="general-category-hint general-category-error" required><option value="">Choose a topic</option><option>General enquiry</option><option>Media and press</option><option>Institutional collaboration</option><option>Other</option></select>')+field(dict(name='message',label='Message',required=True,type='textarea',min=10,max=2000),'general')+'</div><label class="check-line"><input type="checkbox" name="privacy_acknowledgement" required aria-describedby="general-privacy-error"><span>I acknowledge the <button class="policy-link" type="button">Privacy Notice</button>.</span><span class="field-error" id="general-privacy-error" hidden></span></label><div class="honeypot" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="form-bottom"><button class="button" type="submit" disabled>Send Message <span aria-hidden="true">↗</span></button><p class="preview-note">Review preview · no information is sent.</p></div><div class="submit-status" role="status" tabindex="-1"></div><div class="form-confirmation" tabindex="-1" hidden><h3></h3><p></p></div></form></section>'
def shell(current,body):
 prefix='' if current=='home' else '../';page=PAGES.get(current,{});title=page.get('title','OptimIQ Consultus — Expertise for your next step');desc=page.get('description','Explore consulting expertise, independent opportunities and firm partnerships with OptimIQ Consultus.')
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#0F172A"><meta name="description" content="{e(desc)}"><title>{e(title)}</title><link rel="preload" href="{prefix}assets/Inter-Variable.ttf" as="font" type="font/ttf" crossorigin><link rel="preload" href="{prefix}assets/PlusJakartaSans-Variable.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="{prefix}site.css?v=1.2"><script src="{prefix}site-config.js?v=1.2" defer></script><script src="{prefix}public-core.js?v=1.2" defer></script><script src="{prefix}submission-service.js?v=1.2" defer></script><script src="{prefix}site.js?v=1.2" defer></script></head><body data-page="{current}">{header(current,prefix)}<main id="main">{body}</main><div id="mobile-registration" class="mobile-registration" hidden><a class="button" id="mobile-register-action" href="#">Register <span aria-hidden="true">→</span></a></div>{footer(prefix)}<dialog id="policy-dialog" aria-labelledby="policy-title"><div class="form-heading"><h2 id="policy-title">Privacy Notice</h2><form method="dialog"><button class="close-button">Close ×</button></form></div><p>The final Privacy Notice will be available before these forms open for submissions. This review preview does not send or save your information.</p></dialog><noscript><p class="wrap">Enable JavaScript to try the optional calculators and form preview. Audience pages remain available through the navigation links.</p></noscript></body></html>'

def build_home():
 questions={'client':'How much could we save on our next consulting project?','expert':'What could I earn as an independent consultant?','firm':'What is the value of projects we lost or could not take on?'}
 blurbs={'client':'Compare fees using your own project assumptions.','expert':'Explore billable days and a target you choose.','firm':'Put a value on past opportunities lost or declined.'}
 buttons={'client':'Compare Project Fees','expert':'View Earnings Example','firm':'Estimate Missed Projects'}
 direct={'client':'Discuss a project directly','expert':'Apply as a consultant directly','firm':'Discuss a partnership directly'}
 cards=''.join(f'<article class="audience-card" id="{a}-card"><p class="eyebrow">0{i+1} / FOR {A[a]["name"].upper()}</p><h2>{questions[a]}</h2><p>{blurbs[a]}</p><button class="button" data-tool="{a}" aria-expanded="false" aria-controls="{A[a]["homeToolAnchor"]}">{buttons[a]} <span aria-hidden="true">↗</span></button>{action(a,direct[a],klass="text-link")}<a class="learn-more" href="{route(a)}">Learn more for {A[a]["name"].lower()} <span aria-hidden="true">→</span></a></article>' for i,a in enumerate(A))
 hero='<section class="hero"><div class="wrap"><div class="hero-top"><div><p class="eyebrow">CONSULTING EXPERTISE, CONNECTED.</p><h1>The success of your project<br> depends on the <span>people who deliver it.</span></h1><p class="hero-intro">OptimIQ connects organisations with assessed consultants and consulting firms. Find the right expertise and agree clear project terms.</p></div><span class="hero-flourish" aria-hidden="true">↗</span></div><div class="audience-cards">'+cards+'</div><div id="tools">'+''.join(calculator(a,'home',True) for a in A)+'</div><div id="registration-drawers">'+''.join(form(a,'home',True) for a in A)+'</div><div class="hero-bottom"><span>Three perspectives. One connected network.</span><a href="#video">See how OptimIQ works <span aria-hidden="true">↓</span></a></div></div></section>'
 closing='<section class="wrap closing"><div><p class="eyebrow">LET’S MOVE FORWARD</p><h2>Ready to take<br> the next step?</h2></div><div class="closing-actions">'+''.join(action(a,{'client':'Register your interest','expert':'Apply to join','firm':'Discuss a partnership'}[a],klass='button'+(' secondary' if a!='client' else '')) for a in A)+'</div></section>'
 (ROOT/'index.html').write_text(shell('home',hero+video('home','')+closing+general()),encoding='utf-8')
def build_audience(a):
 p=PAGES[a];d=A[a];hero=f'<section class="audience-hero wrap" id="top"><p class="eyebrow">{p["eyebrow"]}</p><h1 data-core>{p["headline"]}</h1><p class="audience-intro" data-core>{p["intro"]}</p><div class="hero-actions">{action(a,p["primary"],"../",a)}<a class="button secondary" href="#{d["toolAnchor"]}" data-tool="{a}">{p["secondary"]} <span aria-hidden="true">↓</span></a></div></section>'
 if a=='client':
  before='<section class="section-band"><div class="wrap content-section" id="team-model"><p class="eyebrow">BUILT AROUND YOUR REQUIREMENT</p><h2 data-core>Flexible team structures for your business goals.</h2><p class="section-intro" data-core>Build the team around the skills, location and time commitment your project needs.</p><div class="team-panels"><article><span class="panel-overline">ON THE GROUND</span><h3 data-core>Regional expertise</h3><p data-core>Consultants for agreed on-site needs and local working context.</p></article><article><span class="panel-overline">CONNECTED ACROSS BORDERS</span><h3 data-core>International specialists</h3><p data-core>Targeted remote contributions for defined areas of expertise.</p></article></div><p class="small-note">Illustrative arrangements, subject to the agreed requirement and availability.</p></div></section>'
  after='<section class="wrap content-section" id="roles"><p class="eyebrow">THE RIGHT CONTRIBUTION</p><h2 data-core>Expertise for the work ahead.</h2>'+rolecards()+'</section><section class="section-band"><div class="wrap content-section" id="practice-areas"><p class="eyebrow">AREAS OF EXPERTISE</p><h2>Recognise your business challenge.</h2>'+practice()+'</div></section>'
 elif a=='expert':
  before='<section class="section-band"><div class="wrap content-section" id="roles"><p class="eyebrow">YOUR PROFESSIONAL PATH</p><h2 data-core>Choose the contribution you want to make.</h2><p class="section-intro" data-core>Explore a role that reflects your experience. Choosing one is optional at this stage.</p>'+rolecards(True)+journey(['Application','Profile and evidence','Professional discussion','Quality review','Assessed standing'])+'<p class="small-note">Assessed standing depends on evaluation. Applying does not guarantee certification or work.</p></div></section>'
  after='<section class="section-band"><div class="wrap content-section standing" id="standing"><p class="eyebrow">CAPABILITY, SUPPORTED BY EVIDENCE</p><h2 data-core>Standing based on what you can deliver.</h2><p data-core>Your experience, completed project results and professional discussion inform evaluation for your chosen role. Relevant opportunities depend on capability, availability and client requirements.</p></div></section>'
 else:
  rows=[('Demonstrating capability','Independent assessment can help present relevant experience and evidence.'),('Finding relevant opportunities','Matching considers verified capabilities and client requirements.'),('Adding specialist capacity','Explore expertise for an agreed requirement, subject to availability.'),('Retaining your identity','Keep your firm’s identity when you pursue opportunities through OptimIQ.')]
  before='<section class="section-band"><div class="wrap content-section" id="challenges"><p class="eyebrow">YOUR CHALLENGES, IN CONTEXT</p><h2 data-core>A partnership shaped around your practice.</h2><div class="challenge-list">'+''.join(f'<article><h3 data-core>{t}</h3><p data-core>{s}</p></article>' for t,s in rows)+'</div></div></section>'
  after='<section class="section-band"><div class="wrap content-section" id="partnership-process"><p class="eyebrow">A CLEAR PATH FORWARD</p><h2 data-core>From first conversation to collaboration.</h2>'+journey(['Registration','Assessment','Opportunity matching','Delivery and collaboration'])+'<p class="section-intro" data-core>Assessed firms become eligible for introductions to pre-qualified projects, subject to client demand. Delivery arrangements and commercial terms are agreed for each engagement.</p></div></section>'
 body=hero+video(a,'../')+before+'<div class="wrap tool-section">'+calculator(a,a)+'</div>'+after+'<section class="wrap form-section">'+form(a,a)+'</section>'+faq(a)+guide(a)
 folder=ROOT/d['route'];folder.mkdir(exist_ok=True);(folder/'index.html').write_text(shell(a,body),encoding='utf-8')
for a in A:build_audience(a)
build_home()
(ROOT/'site-config.js').write_text('window.OptimIQConfig = '+json.dumps(C,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
for a in A:
 folder=ROOT/(A[a]['route']+'-form');folder.mkdir(exist_ok=True);target='../'+A[a]['route']+'/#'+A[a]['formAnchor']
 (folder/'index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta http-equiv="refresh" content="0;url={target}"><title>Continue to OptimIQ</title></head><body><p><a href="{target}">Continue to the short {e(A[a]["name"].lower())} form</a></p></body></html>',encoding='utf-8')
for a in A:
 html=(ROOT/A[a]['route']/'index.html').read_text(encoding='utf-8')
 core=' '.join(re.sub('<[^>]+>','',s) for s in re.findall(r'<(?:h1|h2|h3|p|strong) data-core>(.*?)</(?:h1|h2|h3|p|strong)>',html))
 print(a,'core narrative words:',len(core.split()))
print('Built homepage, three audience pages and three preview legacy navigation routes.')
